window.Lands=(()=>{
const regions='珊瑚の環礁 雲梯の段畑 青砂の水路 白夜の氷浜 葦舟の三角州 紅土の染市 星渡りの草原 石橋の運河市 雨鐘の茶山 灯茸の樹海'.split(' ');
const names=('ラニ モカ ヒナ キリオ タウ レア マイナ オロ ネリオ 潮読みのウズ '+ 'シマ トゥル アナイ パリカ ママル ロコ ピナ クルヤ サルカ タビ '+ 'イルハ ザム ハティ リゼム ナスル サリア ニハド マゼン ハディラ テフ '+ 'ニコル アシェ ヨルム フェリク オグナ シアラ イヌク ベルカ ヘルヤ ミルク '+ 'ケロウ アサギ ドバル ウパラ セレン ナミヤ ユゲ トマリ チナツ ガマル '+ 'アウェ ナルマ コフィ タミヤ レディ ボラン イマリ マロウ サディ ダリヤ '+ 'ホルン エテル ボルカ サルガ トムル ウラク ユリカ テムリ ノヤン グル '+ 'ビノ クララ ドミオ ピエロ ギルダ ロゼッタ カロン マッテ エルヴィ ネスト '+ 'アマ ニルマ テジャ パルナ ソム タラニ メグラ リリヤ ジナ ヴァル '+ 'フクロ サナギ コケリ ヨミネ ホノカ ミツリ キノワ ロウカ ヒイラ オウル').split(' ');
const pic=new Image();pic.src='data:image/png;base64,';
function draw(c,i){c.width=40;c.height=48;if(pic.naturalWidth)c.getContext('2d').drawImage(pic,i%10*40,Math.floor(i/10)*48,40,48,0,0,40,48)}
function role(i){return (i+Math.floor(i/10))%4}
function apply(p,v){if(!/^\d{1,2}$/.test(v||'')||p.role!==role(+v))return;p.landId=+v;p.name=names[+v];p.origin=regions[Math.floor(v/10)]}
function entry(i){let n=600000+i*200;for(;;n++){let j=AlveinDeck.init(n).offers.findIndex(p=>p.role===role(i));if(j>=0)return [n,j]}}
return {names,regions,role,draw,apply,entry,ready:fn=>pic.decode().then(fn)}
})();